def atom(p,*args,positive=True): return {'predicate':p,'args':list(args),'positive':positive}
def add(s,t,**kw): return {'op':'add','source_id':s,'text':t,**kw}
def query(t,a,status): return {'op':'query','text':t,'gold_atom':a,'gold_status':status if isinstance(status,list) else [status]}
def remove(s): return {'op':'remove','source_id':s}
def replace(s,t): return {'op':'replace','source_id':s,'text':t}
cases=[]
def case(i,stratum,events,note,**extra):
    cases.append({'id':i,'stratum':stratum,'events':events,'interpretation_note':note,**extra})
# Hand-written semantic judgments; no production parser, inference or template generator imported.
case('p01','predication_conjunction',[add('a','نديم يقظ.',gold_facts=[atom('يقظ','نديم')]),query('هل نديم يقظ؟',atom('يقظ','نديم'),'SUPPORTED')],'A simple nominal predication; the personal name denotes a local individual.')
