case('p08','predication_conjunction',[add('r','كل مجتهد ناجح.',gold_rules=[{'body':[atom('مجتهد','?x')],'head':atom('ناجح','?x')}]),add('a','فارس مجتهد.',gold_facts=[atom('مجتهد','فارس')]),query('هل فارس ناجح؟',atom('ناجح','فارس'),'SUPPORTED')],'Bare universally quantified predication supplies a one-way implication, not existence or converse.')
case('n01','negation_condition',[add('a','ليست مريم غائبة.',gold_facts=[atom('غائبة','مريم',positive=False)]),query('هل مريم غائبة؟',atom('غائبة','مريم'),'REFUTED')],'Feminine ليست explicitly negates the predication; no absent-fact negation.')
