case('n07','negation_condition',[add('r','إذا لم يكن عادل علامة فإن عادل مجهول.',gold_rules=[{'body':[atom('علامة','عادل',positive=False)],'head':atom('مجهول','عادل')}]),add('a','ليس عادل علامة.',gold_facts=[atom('علامة','عادل',positive=False)]),query('هل عادل مجهول؟',atom('مجهول','عادل'),'SUPPORTED')],'Negative conditional requires explicit negative evidence; لم يكن may remain outside the declared release scope.')
case('n08','negation_condition',[add('r','كل طبيبة متعلمة.',gold_rules=[{'body':[atom('طبيبة','?x')],'head':atom('متعلمة','?x')}]),add('a','مريم طبيبة. ليست سلمى طبيبة.',gold_facts=[atom('طبيبة','مريم'),atom('طبيبة','سلمى',positive=False)]),query('هل مريم متعلمة؟',atom('متعلمة','مريم'),'SUPPORTED'),query('هل سلمى متعلمة؟',atom('متعلمة','سلمى'),'UNKNOWN')],'Rule application matches the subject and sign, without converting a negative premise into a negative conclusion.')
case('d01','nonassertive',[add('a','هل نديم يقظ؟',gold_facts=[],gold_mode='question',gold_query=atom('يقظ','نديم'))],'Question content is not asserted.',must_not_assert=[atom('يقظ','نديم'),atom('يقظ','نديم',positive=False)])
