case('d07','nonassertive',[add('a','لعل عادل موثوق.',gold_facts=[],gold_mode='hope')],'Possibility or hope is not unqualified factual support.',must_not_assert=[atom('موثوق','عادل')],forbid_all_assertions=True)
case('d08','nonassertive',[add('a','هل عادل علامة؟ عادل علامة.',gold_facts=[atom('علامة','عادل')],gold_query=atom('علامة','عادل')),query('هل عادل علامة؟',atom('علامة','عادل'),'SUPPORTED')],'The later explicit assertion licenses the fact; the question does not supply a second independent fact witness.')
