case('a02','ambiguity',[add('a','سليم قابل ماهرا ثم هو مسافر.',gold_facts=[],gold_mode='ambiguous',ambiguity='pronoun_antecedent')],'The antecedent of هو is unresolved between mentioned persons; the whole source may defer.',forbid_all_assertions=True)
case('a03','ambiguity',[add('a','خالد طبيب ماهر.',gold_facts=[],gold_mode='ambiguous',ambiguity='predicate_attribute_boundary')],'No three-token SVO hallucination; the nominal phrase may have structured predication/attribute readings.',forbid_all_assertions=True)
