case('a05','ambiguity',[add('a','لا طالب حاضر.',gold_facts=[],gold_mode='scope_required',ambiguity='negation_of_genus')],'Negation of a class is not a negative unary fact about an individual literally named طالب.',forbid_all_assertions=True)
