corpus={'schema':'nabt.arabic-syntax.independent.v1','created_date':'2026-10-23','authorship':'Independent evaluator, before accessing new reader or runtime implementation','scope':'Hand-authored bounded Arabic challenge; not a random or comprehensive language sample. Semantic statuses are relative to text, not external truth.','cases':cases}
def save(name,data):
    raw=(json.dumps(data,ensure_ascii=False,indent=2)+'\n').encode()
    (OUT/name).write_bytes(raw)
    return hashlib.sha256(raw).hexdigest()
corpus_hash=save('episodes.json',corpus)
metadata=json.loads((REPO/'src/nabt/data/source_evidence/source_manifest.json').read_text())
docs={d['source_id']:d for d in metadata['documents']}
# The query and example substrings are original, exact contiguous bytes. They are
# explicitly marked as quotations/example fragments, never as cleaned full prose.
selections=[
 ('qatr_nominal_example','qatr',153,'الله ربنا','nominal',{'facts':[atom('ربنا','الله')],'opaque_predicate_limit':'The possessive structure of ربنا remains unanalyzed.'}),
 ('qatr_nested_predication','qatr',157,'زيد أبوه قائم','nested_nominal',{'requires_structure_or_defer':True,'forbid_simple_svo':True}),
 ('qatr_fronted_question','qatr',162,'أقاطن قوم سلمى','question',{'facts':[],'requires_structure_or_defer':True}),
 ('qatr_prohibition_result','qatr',112,'لا تدن من الأسد تسلم','prohibition_condition',{'facts':[],'requires_structure_or_defer':True}),
 ('alfiyya_multiple_predicates','alfiyya',207,'وأخبروا باثنين أو بأكثرا ... عن واحد كهم سراة شعرا','instruction',{'facts':[],'requires_structure_or_defer':True}),
 ('alfiyya_exception_instruction','alfiyya',434,'واستثن مجرورا بغير معربا ... بما لمستثنى بألا نسبا','instruction',{'facts':[],'requires_structure_or_defer':True}),
 ('sibawayhi_nominal_example','sibawayhi',1274,'زيد منطلق','nominal',{'facts':[atom('منطلق','زيد')]}),
 ('sibawayhi_polar_question','sibawayhi',1057,'هل زيد منطلق','question',{'facts':[],'query':atom('منطلق','زيد')})]
real=[]
for ident,source,line_no,needle,style,gold in selections:
    data=(REPO/f'src/nabt/data/source_evidence/{source}.txt').read_bytes()
    assert hashlib.sha256(data).hexdigest()==docs[source]['sha256']
    lines=data.splitlines(keepends=True); line=lines[line_no-1]
    encoded=needle.encode(); off=line.find(encoded)
    assert off>=0,(ident,line_no,line.decode())
    start=sum(map(len,lines[:line_no-1]))+off; end=start+len(encoded)
    context_start=sum(map(len,lines[:max(0,line_no-2)])); context_end=sum(map(len,lines[:line_no+1]))
    pages=re.findall(rb'PageV\d+P\d+',data[:start])
    real.append({'id':ident,'source_id':source,'source_sha256':docs[source]['sha256'],'pinned_url':docs[source]['pinned_url'],'source_line_1based':line_no,'page_marker_preceding':pages[-1].decode() if pages else None,'byte_start':start,'byte_end':end,'raw_text':needle,'excerpt_sha256':hashlib.sha256(encoded).hexdigest(),'selection':'Exact contiguous quotation/example fragment; no normalization, no removal inside the interval. Context separately retained.','context_byte_start':context_start,'context_byte_end':context_end,'context_text':data[context_start:context_end].decode(),'style':style,'gold':gold,'license':'CC-BY-NC-SA-4.0'})
real_hash=save('real_excerpts.json',{'schema':'nabt.arabic-syntax.real-excerpts.v1','selection_policy':'Eight purposively selected new intervals from already packaged books. Builders know books, not these selected intervals before freeze. Not an unseen-source test. All intervals differ from prior twelve probes.','examples':real})
protocol={'schema':'nabt.arabic-syntax.protocol.v1','frozen_date':'2026-10-23','episodes_sha256':corpus_hash,'real_excerpts_sha256':real_hash,'counts':{'episodes':40,'strata':5,'per_stratum':8,'real_excerpts':8},'metrics':['complete source-byte restoration','manual atom/rule/query agreement on admitted interpretation','coverage by stratum, never counting safe suspension as comprehension','nonassertive/ambiguous input safety','query statuses on source-relative theory','dependency invalidation after withdrawal/replacement','certificate replay where a certificate is produced'],'release_safety_gates':['No admitted claim contradicts the manually annotated interpretation.','All examined source bytes restore exactly.','No question/command/wish/prohibition or unresolved pronoun supplies an unwarranted assertion.','Every admitted revision episode updates all tested dependencies correctly.'],'coverage_reporting':'Report raw counts and all failures; compare old v1 and new bridge on same bytes. No whole-Arabic or randomly sampled population claim. Unsupported forms count as unrecognized, not successful understanding.','budget':{'per_episode_seconds':5,'total_seconds':180},'noninterference':'Evaluator has read existing docs and original book bytes only; no new implementation or builder tests read before this dataset freeze. Builder receives only hashes and protocol until runtime freeze.','gold_limits':['Natural-language annotations authored by one evaluator; not independently adjudicated linguistic truth.','Some forms may exceed declared implementation scope and intentionally test safe refusal.','Status UNKNOWN and OUT_OF_SCOPE are both accepted only where source withdrawal removes the final predicate signature.','A quoted grammatical example is analyzed as an example; parsing does not claim the example describes the actual world.']}
protocol_hash=save('protocol.json',protocol)
print(json.dumps({'episodes_sha256':corpus_hash,'real_excerpts_sha256':real_hash,'protocol_sha256':protocol_hash,'episodes':len(cases),'real_excerpts':len(real),'query_checkpoints':sum(e['op']=='query' for c in cases for e in c['events'])},indent=2))
